  ('english_grammar', 10, 'intermediate', 'must not과 don''t have to의 의미 차이로 옳은 것은?', 'multiple_choice', '["must not은 금지, don''t have to는 불필요","의미가 같다","must not이 더 약하다","don''t have to가 금지다"]'::jsonb, 'must not은 금지, don''t have to는 불필요', 'must not(금지)과 don''t have to(불필요)는 의미가 다릅니다.'),
  ('english_grammar', 10, 'intermediate', '"It may rain tonight."을 가능성이 더 낮음을 나타내는 문장으로 바꿔 쓰시오.', 'short_answer', null, 'It might rain tonight.', 'might은 may보다 낮은 가능성을 나타냅니다.'),
  ('english_grammar', 10, 'intermediate', '공손한 요청을 나타낼 때 can 대신 쓸 수 있는 조동사를 쓰시오.', 'short_answer', null, 'could', 'could는 can보다 더 공손한 요청을 나타냅니다.'),
  ('english_grammar', 10, 'advanced', '다음 중 must의 의미가 다른 하나는?', 'multiple_choice', '["He must be at home.","You must wear a seatbelt.","You must not smoke here.","Students must submit the form."]'::jsonb, 'He must be at home.', '이것만 강한 추론이고 나머지는 의무를 나타냅니다.'),
